def longest_common_subsequence(seq1, seq2, m, n): 
  # create a table to store lengths of longest common subsequences 
  L = [[0 for x in range(n+1)] for y in range(m+1)] 

  # fill the table in bottom-up manner 
  for i in range(m+1): 
      for j in range(n+1): 
          if i == 0 or j == 0: 
              L[i][j] = 0
          elif seq1[i-1] == seq2[j-1]: 
              L[i][j] = L[i-1][j-1] + 1
          else: 
              L[i][j] = max(L[i-1][j], L[i][j-1]) 

  # L[m][n] will have the length of LCS of seq1 and seq2 
  return L[m][n]

