def is_subset_sum(arr, n, sum): 
    # create a 2D table where dp[i][j] will be True if there exists a subset of arr[0..i-1] with sum j, otherwise False 
    dp = [[False for _ in range(sum+1)] for _ in range(n+1)] 
  
    # fill the first column of the table 
    for i in range(n+1): 
        dp[i][0] = True
  
    # fill the first row of the table 
    for i in range(1, n+1): 
        dp[0][i] = False
  
    # fill the rest of the table 
    for i in range(1, n+1): 
        for j in range(1, sum+1): 
            if arr[i-1] <= j: 
                dp[i][j] = dp[i-1][j] or dp[i-1][j - arr[i-1]] 
            else: 
                dp[i][j] = dp[i-1][j]
  
    return dp[n][sum]

